fn unique_id(prefix: &str) -> String {
    let mut bytes = [0_u8; 8];
    getrandom::getrandom(&mut bytes).expect("the OS random source should be available");
    let suffix: String = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
    format!("{prefix}-{suffix}")
}

async fn enroll_repository(database_url: &str, tenant_id: &str, repository_id: &str, unique: &str) {
    let seed: [u8; 32] = Sha256::digest(format!("key-{unique}").as_bytes()).into();
    let signing_key = SigningKey::from_bytes(&seed);
    let public_key = signing_key.verifying_key().to_bytes();
    let request_id = format!("request-{unique}");
    let node_id = format!("node-{unique}");
    let fingerprint = public_key_fingerprint(&public_key);
    let submission = EnrollmentSubmission {
        request_id: request_id.clone(),
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id.clone(),
        display_name: "Design API integration node".to_string(),
        public_key: public_key.to_vec(),
        public_key_fingerprint: fingerprint.clone(),
        requested_capabilities: vec!["synchronize".to_string()],
        created_at: "2026-01-01T00:00:00Z".to_string(),
        expires_at: "2030-01-01T00:00:00Z".to_string(),
    };
    let request = ActivationChallengeRequest {
        request_id,
        tenant_id: tenant_id.to_string(),
        repository_id: repository_id.to_string(),
        proposed_node_id: node_id,
        public_key_fingerprint: fingerprint,
    };
    let mut enrollment = EnrollmentStore::connect(database_url)
        .await
        .expect("connect enrollment store");
    enrollment
        .submit(&submission)
        .await
        .expect("submit enrollment");
    enrollment
        .approve(&EnrollmentApproval {
            request_id: submission.request_id.clone(),
            tenant_id: tenant_id.to_string(),
            repository_id: repository_id.to_string(),
            public_key_fingerprint: submission.public_key_fingerprint.clone(),
            approved_capabilities: submission.requested_capabilities.clone(),
            approved_by: "design-api-integration-administrator".to_string(),
        })
        .await
        .expect("approve enrollment");
    let nonce: [u8; 32] = Sha256::digest(format!("nonce-{unique}").as_bytes()).into();
    let challenge = enrollment
        .issue_challenge(&request, &nonce, SystemTime::now())
        .await
        .expect("issue enrollment challenge");
    let signature = signing_key.sign(&activation_challenge_bytes(
        &challenge.nonce,
        &request.request_id,
        &request.tenant_id,
        &request.repository_id,
        &request.proposed_node_id,
        &request.public_key_fingerprint,
    ));
    enrollment
        .activate(
            &EnrollmentActivation {
                request,
                nonce: challenge.nonce,
                signature: signature.to_bytes().to_vec(),
            },
            &format!("receipt-{unique}"),
            &format!("signing-key-{unique}"),
            SystemTime::now(),
        )
        .await
        .expect("activate enrollment");
}

async fn application(database_url: &str, tenant_id: &str) -> axum::Router {
    // `industrial_designs`' own migration carries FK references into both
    // `constitution_publications` and `evidence_records` (unconditionally,
    // regardless of whether any row ever sets those columns). Each store's
    // `connect()` only runs its OWN migration, and Cargo runs every
    // `tests/*.rs` file as an independent binary against a shared fresh
    // database with no guaranteed cross-binary ordering -- so this file must
    // create those tables itself rather than rely on some other, unrelated
    // test binary happening to run first (observed failing in CI as
    // "relation \"evidence_records\" does not exist" precisely because
    // nothing else in this binary ever connects an EvidenceStore).
    ConstitutionStore::connect(database_url)
        .await
        .expect("connect Constitution store (industrial_designs' FK dependency)");
    EvidenceStore::connect(database_url)
        .await
        .expect("connect Evidence store (industrial_designs' FK dependency)");

    let designs = Arc::new(Mutex::new(
        DesignStore::connect(database_url)
            .await
            .expect("connect Design store"),
    ));
    let materializations = Arc::new(Mutex::new(
        MaterializationStore::connect(database_url)
            .await
            .expect("connect Design materialization store"),
    ));
    let fleet = Arc::new(
        FleetStore::connect(database_url)
            .await
            .expect("connect Fleet store"),
    );
    design_routes(DesignApiState::new(
        designs,
        materializations,
        fleet,
        Arc::from(tenant_id.to_string()),
    ))
}

async fn body_json(response: axum::response::Response) -> Value {
    let body = to_bytes(response.into_body(), 1_048_576)
        .await
        .expect("read Bridge response body");
    serde_json::from_slice(&body).expect("parse Bridge JSON response")
}

fn post(uri: String, payload: Value) -> Request<Body> {
    Request::builder()
        .method("POST")
        .uri(uri)
        .header("content-type", "application/json")
        .body(Body::from(serde_json::to_vec(&payload).unwrap()))
        .expect("build POST request")
}

#[tokio::test]
async fn proposing_a_design_makes_it_appear_in_the_list() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("design-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let app = application(&database_url, &tenant_id).await;
    let design_id = format!("design-{unique}");

    let propose = app
        .clone()
        .oneshot(post(
            format!("/api/v1/repositories/{repository_id}/designs"),
            json!({
                "design_id": design_id,
                "title": "A proposed design",
                "summary": "a summary",
                "source_version": "v1",
                "constitution_version_id": null,
                "work_task_id": null,
                "evidence_id": null,
                "proposed_by": "agent:proposer",
            }),
        ))
        .await
        .expect("serve propose-design request");
    assert_eq!(propose.status(), StatusCode::CREATED);

    let list = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!("/api/v1/repositories/{repository_id}/designs"))
                .body(Body::empty())
                .expect("build design list request"),
        )
        .await
        .expect("serve design list request");
    assert_eq!(list.status(), StatusCode::OK);
    let list = body_json(list).await;
    assert_eq!(list["total"], json!(1));
    assert_eq!(list["items"][0]["design_id"], json!(design_id));
    assert_eq!(list["items"][0]["lifecycle_state"], json!("proposed"));
}

#[tokio::test]
async fn a_stale_expected_state_is_refused_but_the_current_state_still_lands() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("design-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let app = application(&database_url, &tenant_id).await;
    let design_id = format!("design-{unique}");

    app.clone()
        .oneshot(post(
            format!("/api/v1/repositories/{repository_id}/designs"),
            json!({
                "design_id": design_id,
                "title": "A proposed design",
                "summary": "a summary",
                "source_version": "v1",
                "constitution_version_id": null,
                "work_task_id": null,
                "evidence_id": null,
                "proposed_by": "agent:proposer",
            }),
        ))
        .await
        .expect("serve propose-design request");

    // Two operators both load the design while it is still Proposed, then
    // both submit a decision. The second submission's `expected_lifecycle_state`
    // is now stale -- it must be refused with CONFLICT, not silently applied.
    let first_accept = app
        .clone()
        .oneshot(post(
            format!("/api/v1/repositories/{repository_id}/designs/{design_id}/decisions"),
            json!({
                "decision_kind": "accepted",
                "actor": "agent:reviewer-one",
                "rationale": "looks good",
                "expected_lifecycle_state": "proposed",
            }),
        ))
        .await
        .expect("serve first record-decision request");
    assert_eq!(first_accept.status(), StatusCode::CREATED);

    let stale_reject = app
        .clone()
        .oneshot(post(
            format!("/api/v1/repositories/{repository_id}/designs/{design_id}/decisions"),
            json!({
                "decision_kind": "rejected",
                "actor": "agent:reviewer-two",
                "rationale": "too late",
                "expected_lifecycle_state": "proposed",
            }),
        ))
        .await
        .expect("serve stale record-decision request");
    assert_eq!(stale_reject.status(), StatusCode::CONFLICT);

    let detail = app
        .clone()
        .oneshot(
            Request::builder()
                .uri(format!(
                    "/api/v1/repositories/{repository_id}/designs/{design_id}"
                ))
                .body(Body::empty())
                .expect("build design detail request"),
        )
        .await
        .expect("serve design detail request");
    let detail = body_json(detail).await;
    assert_eq!(detail["design"]["lifecycle_state"], json!("accepted"));
    assert_eq!(
        detail["decisions"].as_array().unwrap().len(),
        2,
        "the stale, rejected decision must not have appended a history row"
    );
}

#[tokio::test]
async fn recording_a_materialization_is_idempotent_and_conflicts_on_reuse() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("design-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let app = application(&database_url, &tenant_id).await;
    let design_id = format!("design-{unique}");

    app.clone()
        .oneshot(post(
            format!("/api/v1/repositories/{repository_id}/designs"),
            json!({
                "design_id": design_id,
                "title": "A proposed design",
                "summary": "a summary",
                "source_version": "v1",
                "constitution_version_id": null,
                "work_task_id": null,
                "evidence_id": null,
                "proposed_by": "agent:proposer",
            }),
        ))
        .await
        .expect("serve propose-design request");

    // The materializations table has a real foreign key into
    // `constitution_publications` -- a materialization must name a
    // publication that genuinely exists, not an arbitrary string.
    let version_id = format!("constitution-{unique}");
    let mut constitution_store = ConstitutionStore::connect(&database_url).await.unwrap();
    constitution_store
        .record_publication(RecordConstitutionPublicationRequest {
            tenant_id: tenant_id.clone(),
            repository_id: repository_id.clone(),
            version_id: version_id.clone(),
            schema_version: "v1".to_string(),
            status: "active".to_string(),
            clauses: vec![ClauseSnapshot {
                id: "clause-a".to_string(),
                slug: "clause-a-slug".to_string(),
                kind: "constraint".to_string(),
                title: "a clause".to_string(),
                statement: "a statement".to_string(),
                status: "active".to_string(),
                consequence: None,
                scope: None,
                rationale: None,
            }],
            source_reference: None,
            source_digest: None,
            published_at: SystemTime::now(),
        })
        .await
        .expect("recording the fixture constitution publication should succeed");

    let materialize_body = json!({
        "actor": "agent:materializer",
        "idempotency_key": format!("idempotency-{unique}"),
        "rationale": "materializing",
        "constitution_version_id": version_id,
        "work_task_ids": [],
        "goal_ids": [],
    });

    let first = app
        .clone()
        .oneshot(post(
            format!("/api/v1/repositories/{repository_id}/designs/{design_id}/materializations"),
            materialize_body.clone(),
        ))
        .await
        .expect("serve first record-materialization request");
    assert_eq!(first.status(), StatusCode::OK);
    let first = body_json(first).await;
    assert_eq!(first["revision_number"], json!(1));

    let retry = app
        .clone()
        .oneshot(post(
            format!("/api/v1/repositories/{repository_id}/designs/{design_id}/materializations"),
            materialize_body.clone(),
        ))
        .await
        .expect("serve identical retry request");
    assert_eq!(
        retry.status(),
        StatusCode::OK,
        "an identical retry must be an idempotent no-op, not a conflict"
    );
    let retry = body_json(retry).await;
    assert_eq!(
        retry["revision_number"],
        json!(1),
        "a retry must return the original revision, not append a new one"
    );

    let mut conflicting_body = materialize_body.clone();
    conflicting_body["rationale"] = json!("a different rationale entirely");

    let conflict = app
        .clone()
        .oneshot(post(
            format!("/api/v1/repositories/{repository_id}/designs/{design_id}/materializations"),
            conflicting_body,
        ))
        .await
        .expect("serve conflicting reuse request");
    assert_eq!(conflict.status(), StatusCode::CONFLICT);
}

#[tokio::test]
async fn every_design_mutation_404s_for_an_unenrolled_repository() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("design-api");
    let tenant_id = format!("tenant-{unique}");
    let unenrolled_repository_id = format!("repository-{unique}");
    let app = application(&database_url, &tenant_id).await;
    let design_id = format!("design-{unique}");

    let propose = app
        .clone()
        .oneshot(post(
            format!("/api/v1/repositories/{unenrolled_repository_id}/designs"),
            json!({
                "design_id": design_id,
                "title": "A proposed design",
                "summary": "a summary",
                "source_version": "v1",
                "constitution_version_id": null,
                "work_task_id": null,
                "evidence_id": null,
                "proposed_by": "agent:proposer",
            }),
        ))
        .await
        .expect("serve propose-design request against an unenrolled repository");
    assert_eq!(propose.status(), StatusCode::NOT_FOUND);

    let decision = app
        .clone()
        .oneshot(post(
            format!(
                "/api/v1/repositories/{unenrolled_repository_id}/designs/{design_id}/decisions"
            ),
            json!({
                "decision_kind": "accepted",
                "actor": "agent:reviewer",
                "rationale": null,
                "expected_lifecycle_state": "proposed",
            }),
        ))
        .await
        .expect("serve record-decision request against an unenrolled repository");
    assert_eq!(decision.status(), StatusCode::NOT_FOUND);

    let materialization = app
        .clone()
        .oneshot(post(
            format!(
                "/api/v1/repositories/{unenrolled_repository_id}/designs/{design_id}/materializations"
            ),
            json!({
                "actor": "agent:materializer",
                "idempotency_key": format!("idempotency-{unique}"),
                "rationale": null,
                "constitution_version_id": format!("constitution-{unique}"),
                "work_task_ids": [],
                "goal_ids": [],
            }),
        ))
        .await
        .expect("serve record-materialization request against an unenrolled repository");
    assert_eq!(materialization.status(), StatusCode::NOT_FOUND);
}
